package main

import (
	"log"
	"log/slog"
	"os"
)

func main() {
	user, code := "alice", 500

	// Unstructured: one opaque string, must be regex-parsed downstream.
	log.Printf("user %s failed with status %d", user, code)
	// Output: 2009/11/10 23:00:00 user alice failed with status 500

	// Structured: typed fields a log backend can index and query.
	logger := slog.New(slog.NewJSONHandler(os.Stdout, nil))
	logger.Error("request failed", "user", user, "status", code)
	// Output: {"time":"...","level":"ERROR","msg":"request failed","user":"alice","status":500}
}

package main

import (
	"log/slog"
	"os"
)

func main() {
	// Text handler: readable in a terminal during development.
	text := slog.New(slog.NewTextHandler(os.Stdout, nil))
	text.Info("server started", "port", 8080)
	// Output: time=... level=INFO msg="server started" port=8080

	// JSON handler: same call site, machine-readable output for prod.
	json := slog.New(slog.NewJSONHandler(os.Stdout, nil))
	slog.SetDefault(json)         // route slog.Info / the log pkg here
	slog.Info("server started", "port", 8080)
	// Output: {"time":"...","level":"INFO","msg":"server started","port":8080}
}

package main

import (
	"log/slog"
	"os"
)

func main() {
	base := slog.New(slog.NewJSONHandler(os.Stdout, nil))

	// With returns a child logger carrying these attrs on every line.
	reqLog := base.With(slog.String("component", "api"), slog.Int("user", 42))
	reqLog.Info("handling request")
	// Output: {...,"msg":"handling request","component":"api","user":42}
	reqLog.Warn("slow query", slog.Duration("took", 0))
	// Output: {...,"msg":"slow query","component":"api","user":42,"took":0}
}

package main

import (
	"log/slog"
	"os"
)

func main() {
	// LevelVar lets you change the threshold at runtime.
	lvl := new(slog.LevelVar)
	lvl.Set(slog.LevelInfo)
	logger := slog.New(slog.NewJSONHandler(os.Stdout, &slog.HandlerOptions{Level: lvl}))

	logger.Debug("cache lookup", "key", "u:42") // dropped: below Info
	logger.Info("user logged in", "user", 42)
	logger.Error("db unreachable", "attempt", 3)
	// Output: {..."level":"INFO","msg":"user logged in","user":42}
	// Output: {..."level":"ERROR","msg":"db unreachable","attempt":3}
}

package main

import (
	"context"
	"log/slog"
	"os"
)

type ctxKey string

const ridKey ctxKey = "reqID"

// ridHandler wraps a Handler and injects the request ID from context.
type ridHandler struct{ slog.Handler }

func (h ridHandler) Handle(ctx context.Context, r slog.Record) error {
	if id, ok := ctx.Value(ridKey).(string); ok {
		r.AddAttrs(slog.String("request_id", id))
	}
	return h.Handler.Handle(ctx, r)
}

func main() {
	logger := slog.New(ridHandler{slog.NewJSONHandler(os.Stdout, nil)})
	ctx := context.WithValue(context.Background(), ridKey, "abc-123")
	logger.InfoContext(ctx, "processing") // ctx carries the ID
	// Output: {...,"msg":"processing","request_id":"abc-123"}
}

package main

import (
	"github.com/rs/zerolog"
	"go.uber.org/zap"
	"os"
)

func main() {
	// zap: strongly typed fields, zero-alloc core logger.
	z, _ := zap.NewProduction()
	defer z.Sync()
	z.Info("user login", zap.String("user", "alice"), zap.Int("attempts", 1))
	// Output: {"level":"info","msg":"user login","user":"alice","attempts":1}

	// zerolog: chained fluent builder, JSON straight to the buffer.
	zl := zerolog.New(os.Stdout).With().Timestamp().Logger()
	zl.Info().Str("user", "alice").Int("attempts", 1).Msg("user login")
	// Output: {"level":"info","user":"alice","attempts":1,"time":"...","message":"user login"}
}

