package main

import (
	"context"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"os"
)

type ctxKey string

const logKey ctxKey = "logger"

// fromCtx returns the request-scoped logger (or the default).
func fromCtx(ctx context.Context) *slog.Logger {
	if l, ok := ctx.Value(logKey).(*slog.Logger); ok {
		return l
	}
	return slog.Default()
}

// RequestLogger stamps a request_id onto a child logger in the context.
func RequestLogger(base *slog.Logger, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		l := base.With(slog.String("request_id", "abc-123"), slog.String("path", r.URL.Path))
		ctx := context.WithValue(r.Context(), logKey, l)
		l.Info("request received")
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

func handler(w http.ResponseWriter, r *http.Request) {
	fromCtx(r.Context()).Info("work done", "items", 3) // same request_id
}

func main() {
	base := slog.New(slog.NewJSONHandler(os.Stdout, nil))
	h := RequestLogger(base, http.HandlerFunc(handler))
	h.ServeHTTP(httptest.NewRecorder(), httptest.NewRequest("GET", "/orders", nil))
}

package main

import (
	"log/slog"
	"os"

	"github.com/rs/zerolog"
	"go.uber.org/zap"
)

func main() {
	user, ms := "alice", 87

	// 1) stdlib slog: typed attrs avoid any-boxing.
	s := slog.New(slog.NewJSONHandler(os.Stdout, nil))
	s.Info("request done", slog.String("user", user), slog.Int("latency_ms", ms))

	// 2) zap: strongly typed fields on the zero-alloc core Logger.
	z, _ := zap.NewProduction()
	defer z.Sync() // flush buffered entries before exit
	z.Info("request done", zap.String("user", user), zap.Int("latency_ms", ms))

	// 3) zerolog: chained fluent builder, JSON straight to the buffer.
	zl := zerolog.New(os.Stdout)
	zl.Info().Str("user", user).Int("latency_ms", ms).Msg("request done")
}

package main

import (
	"time"

	"go.uber.org/zap"
	"go.uber.org/zap/zapcore"
)

func main() {
	cfg := zap.NewProductionConfig()
	// Keep first 100 identical entries per second, then 1 of every 100.
	cfg.Sampling = &zap.SamplingConfig{Initial: 100, Thereafter: 100}
	logger, _ := cfg.Build()
	defer logger.Sync()

	_ = zapcore.InfoLevel
	for i := 0; i < 10_000; i++ {
		// Only a fraction of these identical lines are actually emitted.
		logger.Info("cache miss", zap.String("key", "u:42"))
	}
	time.Sleep(10 * time.Millisecond)
}

