package solution

import (
	"io"
	"log/slog"
)

// NewLeveledLogger returns a JSON logger and the LevelVar controlling it.
// Calling lvl.Set(...) later changes the threshold with no re-creation.
func NewLeveledLogger(w io.Writer, min slog.Level) (*slog.Logger, *slog.LevelVar) {
	lvl := new(slog.LevelVar)
	lvl.Set(min)
	h := slog.NewJSONHandler(w, &slog.HandlerOptions{Level: lvl})
	return slog.New(h), lvl
}

