package solution

import (
	"bytes"
	"log/slog"
	"strings"
	"testing"
)

func TestRuntimeLevel(t *testing.T) {
	var buf bytes.Buffer
	log, lvl := NewLeveledLogger(&buf, slog.LevelInfo)
	log.Info("one")
	if !strings.Contains(buf.String(), "one") {
		t.Fatal("Info should be emitted at Info level")
	}
	buf.Reset()
	lvl.Set(slog.LevelError) // raise threshold at runtime
	log.Info("two")
	if buf.Len() != 0 {
		t.Fatalf("Info should be suppressed at Error level, got %q", buf.String())
	}
}

