func handle(logger *slog.Logger, user string, status int) {
	// Stable message + typed attributes: queryable and allocation-friendly.
	logger.Info("request done",
		slog.String("user", user),
		slog.Int("status", status),
	)
	// Output: {...,"msg":"request done","user":"alice","status":200}
}

type ctxKey string

const ridKey ctxKey = "request_id"

// ContextHandler injects request_id from ctx onto every record.
type ContextHandler struct {
	slog.Handler // embed to inherit Enabled/WithAttrs/WithGroup
}

func (h ContextHandler) Handle(ctx context.Context, r slog.Record) error {
	if id, ok := ctx.Value(ridKey).(string); ok {
		r.AddAttrs(slog.String("request_id", id)) // add before delegating
	}
	return h.Handler.Handle(ctx, r)
}

// Usage: logger := slog.New(ContextHandler{slog.NewJSONHandler(os.Stdout, nil)})

type statusRecorder struct {
	http.ResponseWriter
	status int
}

func (s *statusRecorder) WriteHeader(code int) {
	s.status = code
	s.ResponseWriter.WriteHeader(code)
}

func Logging(l *slog.Logger, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		rec := &statusRecorder{ResponseWriter: w, status: http.StatusOK}
		start := time.Now()
		next.ServeHTTP(rec, r)
		l.Info("request",
			slog.String("method", r.Method),
			slog.String("path", r.URL.Path),
			slog.Int("status", rec.status),
			slog.Duration("latency", time.Since(start)),
		)
	})
}
